This seems to do the trick? For a component like
```js
<SomeFilter attributeName='value' attributeMax='maxValue' attributeMin='minValue' min={0} max={8000} />
```
Probably missing some things but it seems to work. Just tweaked the `connectRange` component.
```js
import { createConnector } from 'react-instantsearch';
import {
  cleanUpValue,
  getIndex,
  refineValue,
  getCurrentRefinementValue,
  getResults,
} from 'react-instantsearch/src/core/indexUtils';

function getId(props) {
  return props.attributeName;
}

const namespace = 'range';

function getCurrentRefinement(props, searchState, context) {
  return getCurrentRefinementValue(
    props,
    searchState,
    context,
    `${namespace}.${getId(props)}`,
    {},
    currentRefinement => {
      let { min, max } = currentRefinement;
      if (typeof min === 'string') {
        min = parseInt(min, 10);
      }
      if (typeof max === 'string') {
        max = parseInt(max, 10);
      }
      return { min, max };
    }
  );
}

function refine(props, searchState, nextRefinement, context) {
  if (!isFinite(nextRefinement.min) || !isFinite(nextRefinement.max)) {
    throw new Error(
      "You can't provide non finite values to the range connector"
    );
  }
  const id = getId(props);
  const nextValue = { [id]: nextRefinement };
  const resetPage = true;
  return refineValue(searchState, nextValue, context, resetPage, namespace);
}

function cleanUp(props, searchState, context) {
  return cleanUpValue(searchState, context, `${namespace}.${getId(props)}`);
}


export default createConnector({
  displayName: 'MultiAttributeRange',

  getProvidedProps(props, searchState, searchResults) {
    const { attributeName, attributeMax, attributeMin } = props;
    let { min, max } = props;

    const hasMin = typeof min !== 'undefined';
    const hasMax = typeof max !== 'undefined';

    const results = getResults(searchResults, this.context);

    if (!hasMin || !hasMax) {
      if (!results) {
        return {
          canRefine: false,
        };
      }

      const maxStats = results.getFacetByName(attributeMax)
        ? results.getFacetStats(attributeMax)
        : null;
      const minStats = results.getFacetByName(attributeMin)
        ? results.getFacetStats(attributeMin)
        : null;

      if (!minStats || !maxStats) {
        return {
          canRefine: false,
        };
      }

      if (!hasMin) {
        min = minStats.min;
      }
      if (!hasMax) {
        max = maxStats.max;
      }
    }

    const count = results
      ? results.getFacetValues(attributeMax).map(v => ({
          value: v.name,
          count: v.count,
        }))
      : [];

    const { min: valueMin = min, max: valueMax = max } = getCurrentRefinement(
      props,
      searchState,
      this.context
    );
    return {
      min,
      max,
      currentRefinement: { min: valueMin, max: valueMax },
      count,
      canRefine: count.length > 0,
    };
  },

  refine(props, searchState, nextRefinement) {
    return refine(props, searchState, nextRefinement, this.context);
  },

  cleanUp(props, searchState) {
    return cleanUp(props, searchState, this.context);
  },

  getSearchParameters(params, props, searchState) {
    const { attributeName, attributeMax, attributeMin } = props;
    const currentRefinement = getCurrentRefinement(
      props,
      searchState,
      this.context
    );
    params = params.addDisjunctiveFacet(attributeMax);
    params = params.addDisjunctiveFacet(attributeMin);

    const { min, max } = currentRefinement;
    if (typeof min !== 'undefined') {
      params = params.addNumericRefinement(attributeMax, '>=', min);
    }
    if (typeof max !== 'undefined') {
      params = params.addNumericRefinement(attributeMin, '<=', max);
    }

    return params;
  }
})
```

